import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`startup-landscape-map`,heroTitle:`Map your startup landscape in minutes`,heroSubtitle:`Perplexity Computer researches hundreds of startups, groups them by function, and delivers a visual landscape map.`,heroCta:`Map my landscape`,inputUrlCta:`Map my landscape`,inputUrlPlaceholder:`e.g. AI video generation`,inputUrlPrefill:`Go to {url} and research this AI subcategory or use case thoroughly. Search Crunchbase, Product Hunt, and other startup databases to find every notable startup in this space. For each company, collect: name, one-line description, funding stage, total raised, founding year, and primary function. Then: 1) Group all startups into 5-8 functional categories based on what they do. 2) Build a sortable database of every startup with all collected fields. 3) Create a visual landscape map organizing companies by category and funding stage. 4) Write a brief market summary highlighting the most funded categories, emerging trends, and whitespace opportunities.`,heroOverlaySteps:[`Researching hundreds of startups across Crunchbase and Product Hunt`,`Collecting funding data, descriptions, and functional categories for each company`,`Grouping startups by function and funding stage into a visual landscape`,`Landscape map, sortable database, and market summary — ready to share`],generatingSteps:[`Analyzing {url} to scope the AI subcategory and define research boundaries`,`Designing an agent to scan Crunchbase, Product Hunt, and startup databases for every notable player`,`Configuring category clustering, funding analysis, and landscape visualization`,`Setting up the sortable database and market summary outputs`],featureSectionTitle:`From subcategory to landscape map`,featureCardTitles:[`Connects to your research stack`,`Outputs you can present`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, and more — Computer plugs into your tools so research, mapping, and tracking happen in one workflow.`,`Visual landscape maps. Sortable startup databases. Funding stage breakdowns. Market trend summaries. Computer delivers work you can drop into a deck or share with your team.`],capabilitySectionTitle:`Your market analyst, on autopilot`,capabilitySectionSubtitle:`Name a category, step away, come back to a complete landscape map.`,capabilityCards:[{title:`Startup Discovery`,description:`Computer can scan Crunchbase, Product Hunt, and dozens of sources to find every notable startup in a category — no manual searching required.`},{title:`Category Clustering`,description:`Computer can group startups into functional segments based on product positioning, use case, and target market — so the landscape tells a clear story.`},{title:`Funding Analysis`,description:`Computer can pull funding rounds, total raised, and investor data for each company — and surface which segments are attracting the most capital.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Notion, Airtable, and more — build workflows that push landscape data wherever your team works.`},{title:`Remember & Learn`,description:`Computer can remember your focus areas, portfolio companies, and past research across sessions — so every landscape builds on what came before.`},{title:`Monitor & Alert`,description:`Computer can watch for new funding rounds, product launches, and market entries — set up a monitoring workflow that pings you when the landscape shifts.`}]});export{t as default};
